let pArr=[];

function setup() {
	createCanvas(540, 540);
	background(0,12,33);
colorMode(RGB, 255)
	angleMode(DEGREES);
	ellipseMode(CENTER);
	noStroke();
	for (let i = 0; i <1080; i++){
		pArr.push(new Mover(width/2+i/4*cos(i), height/2+i/4*sin(i), sin(i), 255*(1-noise(sin(i)*4,cos(i)*4)))); //parameters are x position, y position, size, and greyscale color
	}
}

function draw() {
//background(0,12,33);
	for (let p of pArr) { 
		p.move();
	}
}

class Mover {

constructor(x,y,size,c){
	this.x=x; 
	this.y=y; 
	this.sizeReference = size; 
	this.size = size*3;
	this.xSpeed = -0.5/size;
	this.ySpeed = 0.005/tan(size);
	this.c = color(c, 255-c, c, 3);
	this.w = round(width);
	this.h = round(height);
	this.px = x;
	this.py = y;
}

		move(){
		this.wrap();
		this.px=this.x;
		this.py=this.y;
		this.x+=this.xSpeed*Math.cos((this.px/this.size)/(this.px/this.py))
		this.x+=this.xSpeed*(Math.cos(1/this.size*(this.px/(this.py/this.size))/(this.px/this.py)));
    this.y+=this.ySpeed*Math.sin((this.py/this.size)/(this.py/this.px))
    this.y+=this.ySpeed*(Math.sin(-1/this.size*(this.py/(this.px/this.size))/(this.py/this.px)));
		//this.px = this.x;
		//this.py= this.y;
		stroke(this.c); 
strokeWeight(this.size);
		line(this.x, this.y, this.px, this.py);
	}

	wrap(){
		if (this.x > width) this.x = this.size*1.5;
		if (this.x < 0) this.x = width-this.size*1.5;
		if (this.y > height) this.y = this.size*1.5;
		if (this.y < 0) this.y = height-this.size*1.5;
	}
}

